def split_instruction(text, limit=950):
    """Split at sentence boundaries, preserving every word and its order."""
    pieces = re.split(r'(?:(?<=[.!?])|(?<=[.!?]["”]))\s+(?=[A-Z"“])', text)
    result=[]; current=''
    for piece in pieces:
        if current and len(current)+len(piece)+1>limit:
            result.append(current);current=''
        current=(current+' '+piece).strip()
    if current: result.append(current)
    return result


def build_courses(guide=None):
    guide=Path(guide or Path(__file__).with_name('START HERE - Veteran.txt'))
    topics={t['key']:t for t in HelpSession(guide).topics}
    result=[]
    for key,name,aliases,introductions,sources in COURSES:
        lessons=[{'title':title,'text':text,'reference':False} for title,text in introductions]
        for source in sources:
            topic=topics.get(source)
            if not topic: raise ValueError('Missing tutorial reference: '+source)
            for paragraph in topic['paragraphs']:
                chunks=split_instruction(paragraph)
                lead=re.split(r'(?<=[.!?])\s',paragraph,maxsplit=1)[0].strip()
                title=lead if len(lead)<115 else topic['name']+' — '+lead[:90].rsplit(' ',1)[0]
                for index,chunk in enumerate(chunks):
                    lessons.append({'title':'Command reference: '+title+(' — part '+str(index+1) if len(chunks)>1 else ''),'text':chunk,'reference':True})
        if key=='options':
            for category in CATEGORIES:
                for field in fields(category,{}):
                    if field.kind=='action': explanation='This is an action button. Enter or its spoken action opens '+field.label+'. Opening another activity closes Options and discards unsaved edits in this category.'
                    elif field.kind=='password': explanation='This is a hidden credential entry. Its contents are not spoken. A blank value keeps the saved key; enter a replacement privately. Consent is a separate checkbox. OK saves and Cancel leaves the existing key unchanged.'
                    elif field.kind=='check': explanation='This is a checkbox. Space toggles it. By voice move to this setting and say on or off. OK commits the category; Cancel discards staged changes.'
                    elif field.kind=='headers': explanation='Choose from From, Subject, Date and Size. Space includes or excludes a header; Alt Up and Alt Down reorder it. Keep at least one. OK saves the order; Cancel restores it.'
                    else:
                        values=field.choices
                        if field.key in ('rate','pitch'): choices='Choose a whole number from minus ten to ten.'
                        elif field.key=='volume': choices='Choose a percentage from zero to one hundred.'
                        elif field.key=='document_size': choices='Choose a size from six to seventy-two points.'
                        elif field.key=='podcast_limit': choices='Choose manual, all, or a whole number from one to ten thousand. This applies to the selected subscription.'
                        else: choices=('Available choices: '+', '.join(values)+'.') if values else 'Available values depend on your installed voices, accounts or subscriptions.' if field.kind=='choice' else 'Type or speak the value in this text field.'
                        explanation=choices+' Tab reaches the control; arrows change a listed choice. Say '+field.key.replace('_',' ')+' followed by the value to stage it. OK saves; Cancel discards unconfirmed edits.'
                        if field.key in ('rate','pitch','volume'):explanation+=' Listen to the preview before saving. Control stops a preview; Escape cancels the category.'
                    lessons.append({'title':category+': '+field.label,'text':category+'. '+field.label+'. '+explanation,'reference':False})
        # Command entries retain whole paragraphs: explanations must not lose the
        # conditions/corrections later in a long paragraph when looked up.
        commands={}
        for lesson in lessons:
            if lesson['reference']:continue
            for phrase in re.findall(r'["“]([^"”]+)["”]',lesson['text']):
                if len(phrase)<130 and not phrase.endswith('...'):
                    commands.setdefault(phrase.rstrip('.,!?').casefold(),{'title':phrase.rstrip('.,!?'),'text':lesson['text']})
        for source in sources:
            for paragraph in topics[source]['paragraphs']:
                for phrase in re.findall(r'["“]([^"”]+)["”]',paragraph):
                    if len(phrase)<130 and not phrase.endswith('...'):
                        key_phrase=phrase.rstrip('.,!?').casefold()
                        if key_phrase in commands:
                            entry=commands[key_phrase]
                            if paragraph not in entry['text']:entry['text']+='\n\n'+paragraph
                        else:commands[key_phrase]={'title':phrase.rstrip('.,!?'),'text':paragraph}
        result.append({'key':key,'name':name,'aliases':aliases,'lessons':lessons,'commands':list(commands.values())})
    return result
